def seed():
    db = SessionLocal()
    try:
        for tmpl in TEMPLATES:
            existing = db.query(WorkflowTemplate).filter(WorkflowTemplate.slug == tmpl["slug"]).first()
            now = datetime.datetime.utcnow()
            if existing:
                existing.name = tmpl["name"]
                existing.category = tmpl["category"]
                existing.definition = tmpl["definition"]
                existing.updated_at = now
                # Also update the latest version row so new notebooks get the correct snapshot
                latest_ver = (
                    db.query(WorkflowTemplateVersion)
                    .filter(WorkflowTemplateVersion.template_id == existing.id)
                    .order_by(WorkflowTemplateVersion.version.desc())
                    .first()
                )
                if latest_ver:
                    latest_ver.definition = tmpl["definition"]
                    latest_ver.saved_at = now
                print(f"Updated: {tmpl['slug']}")
            else:
                t = WorkflowTemplate(
                    id=uuid.uuid4(),
                    slug=tmpl["slug"],
                    name=tmpl["name"],
                    category=tmpl["category"],
                    version=1,
                    is_active=True,
                    definition=tmpl["definition"],
                    created_at=now,
                    updated_at=now,
                )
                db.add(t)
                db.add(WorkflowTemplateVersion(
                    id=uuid.uuid4(),
                    template_id=t.id,
                    version=1,
                    definition=tmpl["definition"],
                    saved_at=now,
                ))
                print(f"Created: {tmpl['slug']}")
        db.commit()
        print("Done.")
    finally:
        db.close()


if __name__ == "__main__":
    seed()


